/*
 * A049067  LaBar's conjecture (steps to return n to 1 after division by 3
 *          and, if needed, multiplication by 2, addition of 1 or 2).
 * https://oeis.org/A049067
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = sum of all numbers in the trajectory starting at n where
 *            the trajectory is generated by: if n % 3 == 0 then n = n / 3
 *            else if toggle=0 then n = 2*n + 2 else n = 2*n + 1 with toggle
 *            alternating between 0 and 1 for every non‑divisible‑by‑3 step.
 *            The progression starts with n itself and ends...
 * Range:     u8 n <= 12, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    seq_t cur = (seq_t)n;
    seq_t sum = cur;          /* include the initial n */
    unsigned int toggle = 0;  /* 0 -> next 2*n+2, 1 -> next 2*n+1 */

    do
    {
        if ((cur % (seq_t)3) == (seq_t)0)
        {
            cur = cur / (seq_t)3;
        }
        else
        {
            if (toggle == 0)
                cur = cur * (seq_t)2 + (seq_t)2;
            else
                cur = cur * (seq_t)2 + (seq_t)1;

            toggle ^= 1;
        }
        sum += cur;
    }
    while (cur != (seq_t)1);

    return sum;
}
